static void kfree_skbmem(struct sk_buff *skb) /* <=== kfree_skbmem */ 
{
	struct sk_buff *other;
	atomic_t *fclone_ref;

	switch (skb->fclone) {
	case SKB_FCLONE_UNAVAILABLE:
		kmem_cache_free(skbuff_head_cache, skb);
		break;

	case SKB_FCLONE_ORIG:
		fclone_ref = (atomic_t *) (skb + 2);
		if (atomic_dec_and_test(fclone_ref))
			kmem_cache_free(skbuff_fclone_cache, skb);
		break;

	case SKB_FCLONE_CLONE:
		fclone_ref = (atomic_t *) (skb + 1);
		other = skb - 1;

		/* The clone portion is available for
		 * fast-cloning again.
		 */
		skb->fclone = SKB_FCLONE_UNAVAILABLE;

		if (atomic_dec_and_test(fclone_ref))
			kmem_cache_free(skbuff_fclone_cache, other);
		break;
	}
}

static inline int atomic_read(const atomic_t *v) /* <=== atomic_read */ 
{
	return (*(volatile int *)&(v)->counter);
}

void skb_queue_head(struct sk_buff_head *list, struct sk_buff *newsk) /* <=== skb_queue_head */ 
{
	unsigned long flags;

	spin_lock_irqsave(&list->lock, flags);
	__skb_queue_head(list, newsk);
	spin_unlock_irqrestore(&list->lock, flags);
}

unsigned char *skb_pull(struct sk_buff *skb, unsigned int len) /* <=== skb_pull */ 
{
	return skb_pull_inline(skb, len);
}

static __inline__ int atomic_dec_and_test(atomic_t *v) /* <=== atomic_dec_and_test */ 
{
	unsigned long flags;
	int ret;
	local_irq_save(flags);
	--v->counter;
	ret = v->counter;
	local_irq_restore(flags);
	return ret == 0;
}

static inline unsigned long /* <=== copy_to_user */ 
copy_to_user(void *to, const void *from, unsigned long len)
{
	unsigned long over;

	if (access_ok(VERIFY_WRITE, to, len))
		return __copy_tofrom_user(to, from, len);

	if ((unsigned long)to < TASK_SIZE) {
		over = (unsigned long)to + len - TASK_SIZE;
		return __copy_tofrom_user(to, from, len - over) + over;
	}
	return len;
}

static inline int atomic_dec_and_test(atomic_t *v) /* <=== atomic_dec_and_test */ 
{
	unsigned char c;

	asm volatile(LOCK_PREFIX "decl %0; sete %1"
		     : "+m" (v->counter), "=qm" (c)
		     : : "memory");
	return c != 0;
}

void kfree_skb(struct sk_buff *skb) /* <=== kfree_skb */ 
{
	if (unlikely(!skb))
		return;
	if (likely(atomic_read(&skb->users) == 1))
		smp_rmb();
	else if (likely(!atomic_dec_and_test(&skb->users)))
		return;
	trace_kfree_skb(skb, __builtin_return_address(0));
	__kfree_skb(skb);
}

static inline int atomic_dec_and_test(volatile atomic_t *v) /* <=== atomic_dec_and_test */ 
{
	int retval;
	unsigned long flags;
	cris_atomic_save(v, flags);
	retval = --(v->counter) == 0;
	cris_atomic_restore(v, flags);
	return retval;
}

static inline int atomic_dec_and_test(atomic_t *v) /* <=== atomic_dec_and_test */ 
{
	char c;
	__asm__ __volatile__("subql #1,%1; seq %0" : "=d" (c), "+m" (*v));
	return c != 0;
}

int put_cmsg(struct msghdr * msg, int level, int type, int len, void *data) /* <=== put_cmsg */ 
{
	struct cmsghdr __user *cm
		= (__force struct cmsghdr __user *)msg->msg_control;
	struct cmsghdr cmhdr;
	int cmlen = CMSG_LEN(len);
	int err;

	if (MSG_CMSG_COMPAT & msg->msg_flags)
		return put_cmsg_compat(msg, level, type, len, data);

	if (cm==NULL || msg->msg_controllen < sizeof(*cm)) {
		msg->msg_flags |= MSG_CTRUNC;
		return 0; /* XXX: return error? check spec. */
	}
	if (msg->msg_controllen < cmlen) {
		msg->msg_flags |= MSG_CTRUNC;
		cmlen = msg->msg_controllen;
	}
	cmhdr.cmsg_level = level;
	cmhdr.cmsg_type = type;
	cmhdr.cmsg_len = cmlen;

	err = -EFAULT;
	if (copy_to_user(cm, &cmhdr, sizeof cmhdr))
		goto out;
	if (copy_to_user(CMSG_DATA(cm), data, cmlen - sizeof(struct cmsghdr)))
		goto out;
	cmlen = CMSG_SPACE(len);
	if (msg->msg_controllen < cmlen)
		cmlen = msg->msg_controllen;
	msg->msg_control += cmlen;
	msg->msg_controllen -= cmlen;
	err = 0;
out:
	return err;
}

static inline int atomic_read(const atomic_t *v) /* <=== atomic_read */ 
{
	return (v)->counter;
}

static inline int atomic_read(const atomic_t *v) /* <=== atomic_read */ 
{
	return ACCESS_ONCE(v->counter);
}

static void skb_release_all(struct sk_buff *skb) /* <=== skb_release_all */ 
{
	skb_release_head_state(skb);
	skb_release_data(skb);
}

static inline void spin_unlock_irqrestore(spinlock_t *lock, unsigned long flags) /* <=== spin_unlock_irqrestore */ 
{
	raw_spin_unlock_irqrestore(&lock->rlock, flags);
}

static inline unsigned long /* <=== copy_to_user */ 
copy_to_user(void *to, const void *from, unsigned long n)
{
	unsigned long over;

	if (access_ok(VERIFY_WRITE, to, n))
		return __copy_tofrom_user(to, from, n);
	if ((unsigned long)to < TASK_SIZE) {
		over = (unsigned long)to + n - TASK_SIZE;
		return __copy_tofrom_user(to, from, n - over) + over;
	}
	return n;
}

